function w({registerIndicator:g,sourceValues:y,nulls:b}){g({id:"oa-nlma",name:"Non-Lag Moving Average (NLMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:14,min:2,max:200,step:1,tooltip:"Conceptual averaging period. The kernel itself spans 5 * period - 1 bars."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"nlma",type:"line",title:"NLMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,p){const r=Math.max(2,Math.min(200,Math.floor(Number(p.period)||14))),a=y(i,p.source??"close"),n=r-1,h=4,l=r*4+n,M=3*Math.PI,u=new Array(l).fill(0);let f=0;for(let e=0;e<=l-2;e++){let t=0;if(e<=n-1)t=n>1?e/(n-1):0;else{const k=(e-n+1)*(2*h-1),d=h*r-1;t=1+(d>0?k/d:0)}const c=Math.cos(Math.PI*t),s=(t<=.5?1:1/(M*t+1))*c;u[e]=s,f+=s}u[l-1]=0;const N=Math.abs(f)>1e-15,m=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const t=Number.isFinite(a[e])?a[e]:0;if(e+1<l){m[e]=t;continue}let c=0;for(let o=0;o<l;o++){const s=Number.isFinite(a[e-o])?a[e-o]:0;c+=s*u[o]}m[e]=N?c/f:t}return{nlma:b(m)}}})}export{w as default};
